import 'dart:convert';
import 'dart:typed_data';

class TryloLogoData {
  TryloLogoData._();

  /// Base64 encoded high-resolution asset of the official Trylo squircle heart-arrows logo.
  /// Works completely standalone and in-memory without needing asset bundle reloads.
  static const String base64Png = '';

  static Uint8List? _cachedBytes;

  static Uint8List get bytes {
    return _cachedBytes ??= base64Decode(base64Png);
  }
}
